// BEGIN AE FINAL TEMPORARY AVAILABILITY PROBE
#[inline(never)]
fn ae17_scan(ranges: &[LocalLiveRange], output: &mut Vec<usize>) -> usize {
    output.clear();
    let mut inspected = 0;
    for pc in (0..ranges.len() * 2).rev() {
        output.extend(
            ranges
                .iter()
                .filter(|range| {
                    inspected += 1;
                    range.start <= pc && pc < range.end
                })
                .map(|range| range.slot.index()),
        );
    }
    inspected
}

#[inline(never)]
fn ae17_index(ranges: &[LocalLiveRange], output: &mut Vec<usize>) -> (usize, usize) {
    output.clear();
    let mut build = 0;
    let index = DebugAvailability::new(ranges, |n| {
        build += n;
        Ok::<_, ()>(())
    })
    .unwrap();
    let mut queries = 0;
    for pc in (0..ranges.len() * 2).rev() {
        index
            .visit(
                pc,
                |n| {
                    queries += n;
                    Ok::<_, ()>(())
                },
                |slot| output.push(slot.index()),
            )
            .unwrap();
    }
    std::hint::black_box(&index);
    (build, queries)
}

#[test]
#[ignore = "temporary matched release measurement"]
fn ae_final_measurement_availability() {
    use std::{hint::black_box, time::Instant};

    for (count, batch) in [(1usize, 16_384usize), (16, 2_048), (256, 64), (4_096, 2)] {
        let ranges = (0..count)
            .rev()
            .map(|i| range(i, i * 2, i * 2 + 1))
            .collect::<Vec<_>>();
        let expected = (0..count).rev().collect::<Vec<_>>();
        let mut scanned = Vec::with_capacity(count);
        let mut indexed = Vec::with_capacity(count);
        let scan_work = ae17_scan(&ranges, &mut scanned);
        let (build_work, query_work) = ae17_index(&ranges, &mut indexed);
        assert_eq!(scanned, expected);
        assert_eq!(indexed, scanned);
        assert_eq!(scan_work, count * count * 2);
        let mut scan_samples = Vec::new();
        let mut index_samples = Vec::new();
        let mut scan_warmup = 0;
        let mut index_warmup = 0;
        for round in 0..8 {
            for index_algorithm in if round % 2 == 0 {
                [false, true]
            } else {
                [true, false]
            } {
                let started = Instant::now();
                let mut work = (0usize, 0usize);
                for _ in 0..batch {
                    if index_algorithm {
                        let charged = ae17_index(black_box(&ranges), black_box(&mut indexed));
                        work.0 += charged.0;
                        work.1 += charged.1;
                        black_box(&indexed);
                    } else {
                        work.0 += ae17_scan(black_box(&ranges), black_box(&mut scanned));
                        black_box(&scanned);
                    }
                }
                let elapsed = started.elapsed().as_nanos();
                if index_algorithm {
                    assert_eq!(indexed, expected);
                    assert_eq!(work, (build_work * batch, query_work * batch));
                    if round == 0 {
                        index_warmup = elapsed;
                    } else {
                        index_samples.push(elapsed);
                    }
                } else {
                    assert_eq!(scanned, expected);
                    assert_eq!(work, (scan_work * batch, 0));
                    if round == 0 {
                        scan_warmup = elapsed;
                    } else {
                        scan_samples.push(elapsed);
                    }
                }
            }
        }
        println!("AE_RESULT {{\"kind\":\"availability\",\"ranges\":{count},\"queries\":{},\"max_overlap\":1,\"batch\":{batch},\"outputs\":{count},\"scan_inspections\":{scan_work},\"build_work\":{build_work},\"query_work\":{query_work},\"query_nodes\":{},\"scratch_bytes\":{},\"scan_warmup_ns\":{scan_warmup},\"index_warmup_ns\":{index_warmup},\"scan_samples_ns\":{scan_samples:?},\"index_samples_ns\":{index_samples:?}}}", count * 2, query_work - count, DebugAvailability::scratch_bytes(count));
    }
}
// END AE FINAL TEMPORARY AVAILABILITY PROBE

