//! Temporary current-only AE03 SDK integration measurement; no JIT or AOT.
use kagari::{
    BytecodeArtifact,
    context::ExecutionContext,
    engine::{
        KagariEngine,
        source::{ArtifactOptions, PreparationOptions},
    },
    program::PreparedProgram,
};
use kagari_bytecode::instruction::BytecodeInstruction;
use kagari_runtime::{module::entry::ProgramEntry, value::Value};
use kagari_source::source::SourceFile;
use std::{env, error::Error, fs, path::PathBuf, time::Instant};

const SOURCE: &str = r#"fn adjust(value: i32, positive: bool) -> i32 {
    101;
    102;
    value == 7;
    val original = value;
    var answer = original;
    if positive {
        201;
        original != 0;
        val increment = 2;
        answer += increment;
        202;
    } else {
        301;
        val decrement = 2;
        answer -= decrement;
        original == 9;
    }
    401;
    answer
}

fn main() -> i32 {
    501;
    val seed = 40;
    val raised = adjust(seed, true);
    var result = 0;
    if raised == 42 {
        val final_value = raised;
        result = final_value;
    } else {
        result = adjust(seed, false);
    }
    502;
    result
}
"#;

struct Samples {
    raw: String,
    outcomes: String,
    state: &'static str,
    sample: usize,
}

impl Samples {
    fn measure<T>(&mut self, route: &str, phase: &str, operation: impl FnOnce() -> T) -> T {
        let start = Instant::now();
        let value = operation();
        let ns = start.elapsed().as_nanos();
        self.raw.push_str(&format!(
            "{},{},{route},{phase},{ns}\n",
            self.state, self.sample
        ));
        value
    }

    fn execute(&mut self, route: &str, engine: &KagariEngine, program: &PreparedProgram) {
        let context = ExecutionContext::default();
        let mut runtime = self.measure(route, "runtime_setup", || engine.runtime(context.clone()));
        let loaded = self
            .measure(route, "runtime_link", || {
                runtime.load_program(program, Default::default())
            })
            .expect("runtime linking");
        let report = self
            .measure(route, "first_execution", || {
                runtime.execute(&loaded, ProgramEntry::Main, &[], &context)
            })
            .expect("first main execution");
        assert_eq!(
            report.return_value.value(runtime.runtime().gc()).unwrap(),
            Value::I32(42)
        );

        // Inspect retained facts outside all phase timers.
        let mut functions = 0;
        let mut locals = 0;
        let mut branches = 0;
        for module in program.bytecode().modules() {
            for function in &module.functions {
                functions += 1;
                locals += function.metadata.debug.local_live_ranges.len();
                branches += function
                    .instructions
                    .iter()
                    .filter(|instruction| {
                        matches!(
                            instruction,
                            BytecodeInstruction::Branch { .. }
                                | BytecodeInstruction::PredicateBranch { .. }
                        )
                    })
                    .count();
            }
        }
        assert!(locals > 0, "debug local ranges retained");
        assert!(branches >= 2, "both function branch sites retained");
        self.outcomes.push_str(&format!(
            "{},{},{route},I32(42),{functions},{locals},{branches},{}\n",
            self.state,
            self.sample,
            program.has_native_input(),
        ));
    }

    fn direct(&mut self) {
        let route = "direct";
        let engine = self.measure(route, "engine_setup", KagariEngine::default);
        let source = SourceFile::new("ae03_sdk.kgr", SOURCE);
        let options = PreparationOptions::default();
        let program = self
            .measure(route, "compile_to_program", || {
                engine.compile_to_program(source, options)
            })
            .expect("direct source preparation");
        assert!(!program.has_native_input());
        self.execute(route, &engine, &program);
    }

    fn staged(&mut self) {
        let route = "staged_source";
        let engine = self.measure(route, "engine_setup", KagariEngine::default);
        let source = SourceFile::new("ae03_sdk.kgr", SOURCE);
        let checked = self
            .measure(route, "source_check", || engine.compile_source(source))
            .expect("source checking");
        let options = PreparationOptions::default();
        let program = self
            .measure(route, "source_lower_prepare", || {
                engine.prepare(&checked, options)
            })
            .expect("checked source lowering/preparation");
        assert!(!program.has_native_input());
        self.execute(route, &engine, &program);
    }

    fn artifact(&mut self) -> Vec<u8> {
        let route = "artifact";
        let engine = self.measure(route, "engine_setup", KagariEngine::default);
        let source = SourceFile::new("ae03_sdk.kgr", SOURCE);
        let options = ArtifactOptions::default();
        let artifact = self
            .measure(route, "compile_to_artifact", || {
                engine.compile_to_artifact(source, options)
            })
            .expect("explicit artifact export");
        let bytes = self
            .measure(route, "artifact_encode", || {
                artifact.records().to_bytes(artifact.definitions())
            })
            .expect("artifact serialization");
        let decoded = self
            .measure(route, "artifact_decode", || {
                BytecodeArtifact::from_bytes(&bytes)
            })
            .expect("artifact decoding");
        let compatibility = Default::default();
        let cancel = Default::default();
        let program = self
            .measure(route, "artifact_prepare", || {
                PreparedProgram::from_artifact(decoded, &compatibility, &cancel)
            })
            .expect("source-free artifact preparation");
        assert!(program.has_native_input());
        self.execute(route, &engine, &program);
        bytes
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let output = PathBuf::from(env::args().nth(1).expect("output directory argument"));
    assert!(
        output.is_dir(),
        "create output directory before measurement"
    );
    let mut samples = Samples {
        raw: "state,sample,route,phase,ns\n".into(),
        outcomes:
            "state,sample,route,result,functions,debug_local_ranges,branches,has_native_input\n"
                .into(),
        state: "warmup",
        sample: 0,
    };
    let mut last_artifact = Vec::new();
    // Exactly one explicit full warmup, followed by five full measured samples.
    // Each route gets a fresh engine/source session and fresh runtime every time.
    for iteration in 0..6 {
        samples.state = if iteration == 0 { "warmup" } else { "measured" };
        samples.sample = iteration;
        samples.direct();
        samples.staged();
        last_artifact = samples.artifact();
    }
    fs::write(output.join("samples.csv"), samples.raw)?;
    fs::write(output.join("outcomes.csv"), samples.outcomes)?;
    fs::write(output.join("sample.kgr"), SOURCE)?;
    fs::write(output.join("sample.kbc"), &last_artifact)?;
    println!(
        "Completed one warmup + five measured samples per route; all 18 executions returned I32(42); artifact {} bytes.",
        last_artifact.len()
    );
    Ok(())
}
